// Packet Observatory design: terminal-first, asymmetric lab console; IBM Plex Sans + IBM Plex Mono; cyan traces, amber focus, coral errors.
import { useMemo, useState } from "react";
import { Check, ChevronRight, CircleHelp, Copy, ExternalLink, Gauge, Network, Play, RotateCcw, TerminalSquare, Wifi } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

type DeviceName = "R1" | "R2";
type Mode = "user" | "privileged" | "config" | "interface";
type InterfaceName = "g0/0" | "loopback0" | null;
type InterfaceState = { global?: string; linkLocal?: string; up: boolean };
type DeviceState = { mode: Mode; context: InterfaceName; forwarding: boolean; interfaces: { "g0/0": InterfaceState; loopback0: InterfaceState }; routes: string[]; history: string[] };
type LabState = { activeDevice: DeviceName; verified: boolean; devices: Record<DeviceName, DeviceState> };

type Step = { id: number; code: string; eyebrow: string; title: string; description: string; device: "R1" | "R2" | "BOTH"; hint: string; explain: string };

const steps: Step[] = [
  { id: 1, code: "01", eyebrow: "ACCESS", title: "Enter privileged EXEC mode", description: "Start on R1. Move from user EXEC to privileged EXEC so the router will accept configuration commands.", device: "R1", hint: "The command is a single word: enable", explain: "The # prompt indicates privileged EXEC mode." },
  { id: 2, code: "02", eyebrow: "FORWARDING", title: "Enable IPv6 forwarding", description: "Turn the router into an IPv6 router. This is the global prerequisite for forwarding packets between interfaces.", device: "R1", hint: "Enter configuration mode first, then use ipv6 unicast-routing.", explain: "IPv6 forwarding is a global router setting, not an interface setting." },
  { id: 3, code: "03", eyebrow: "ADDRESSING", title: "Configure R1’s transit interface", description: "Give G0/0 a global address and a predictable link-local address, then bring the interface up.", device: "R1", hint: "Use 2001:db8:12:12::1/64 and fe80::1 on G0/0, then no shutdown.", explain: "The /64 prefix identifies the shared transit network. The link-local address stays on that link." },
  { id: 4, code: "04", eyebrow: "SIMULATED LAN", title: "Configure R1’s loopback", description: "Use Loopback0 as a stable simulated LAN prefix so the lab can test routing without a switch or PC.", device: "R1", hint: "Select interface loopback 0 and use 2001:db8:1::1/64.", explain: "The loopback creates a connected route for 2001:db8:1::/64." },
  { id: 5, code: "05", eyebrow: "PEER CONFIG", title: "Configure R2", description: "Switch to R2 and mirror the transit and loopback design with R2’s addresses.", device: "R2", hint: "On R2 use ::2 on the transit link, fe80::2 as link-local, and 2001:db8:2::1/64 on Loopback0.", explain: "Both routers now share one transit prefix and each owns one unique LAN prefix." },
  { id: 6, code: "06", eyebrow: "ROUTING", title: "Add static routes", description: "Tell each router how to reach the remote loopback. Use the neighbor’s link-local address and the transit interface.", device: "BOTH", hint: "R1 routes 2001:db8:2::/64 via fe80::2 g0/0. R2 routes 2001:db8:1::/64 via fe80::1 g0/0.", explain: "The routing table now has an explicit path to the remote simulated LAN." },
  { id: 7, code: "07", eyebrow: "EVIDENCE", title: "Verify the path", description: "Run a reachability test from R1 to R2’s loopback. The packet should cross the transit link and arrive at 2001:db8:2::1.", device: "R1", hint: "On R1, run ping ipv6 2001:db8:2::1. You can also inspect show ipv6 route and show ipv6 neighbors.", explain: "A successful ping confirms addressing, forwarding, routing, and neighbor discovery align." },
];

type CurriculumLab = { id: number; code: string; title: string; domain: string; blurb: string; topology: string; skills: string[]; steps: { title: string; command: string; why: string }[] };
const curriculumLabs: CurriculumLab[] = [
  { id: 1, code: "LAB 01", title: "Addressing + CLI Foundations", domain: "Network Fundamentals", blurb: "Build the mental model: modes, Ethernet, MAC addresses, IPv4 subnetting, and dual-stack interface verification.", topology: "R1 · SW1 · two dual-stack hosts", skills: ["MAC learning", "IPv4 subnetting", "IPv6 prefixes", "show / ping"], steps: [{ title: "Enter privileged mode", command: "enable", why: "Move from user EXEC to a command level that can configure the device." }, { title: "Inspect interfaces", command: "show ip interface brief", why: "Read interface state and IPv4 addressing at a glance." }, { title: "Inspect MAC learning", command: "show mac address-table", why: "See how a switch maps learned source MAC addresses to ports." }, { title: "Verify IPv6", command: "show ipv6 interface brief", why: "Confirm IPv6 addresses and interface state." }] },
  { id: 2, code: "LAB 02", title: "Switching, VLANs + Trunks", domain: "Network Access", blurb: "Separate broadcast domains and carry them across a trunk with VLANs, LACP, STP, and inter-VLAN routing.", topology: "SW1 ⇄ SW2 · VLANs 10/20/99 · router-on-a-stick", skills: ["Access ports", "802.1Q trunks", "LACP", "Rapid PVST+"], steps: [{ title: "Create VLANs", command: "vlan 10", why: "Create a logical broadcast domain for users." }, { title: "Assign an access port", command: "switchport mode access", why: "Place an edge port into a single VLAN." }, { title: "Configure a trunk", command: "switchport mode trunk", why: "Carry tagged VLAN traffic between switches." }, { title: "Inspect spanning tree", command: "show spanning-tree", why: "Read root, port roles, and forwarding state." }] },
  { id: 3, code: "LAB 03", title: "Routing + OSPF", domain: "IP Connectivity", blurb: "Read routing tables, install IPv4/IPv6 static routes, then form a single-area OSPFv2 adjacency across three routers.", topology: "R1 ⇄ R2 ⇄ R3 · redundant dual-stack paths", skills: ["Longest match", "Static routes", "OSPFv2", "Router IDs"], steps: [{ title: "Inspect the route table", command: "show ip route", why: "Identify protocol codes, next hops, distance, and metric." }, { title: "Add an IPv4 route", command: "ip route 10.30.0.0 255.255.255.0 10.12.0.2", why: "Create a manually selected path to a remote network." }, { title: "Start OSPF", command: "router ospf 1", why: "Enter the process that will discover and advertise routes." }, { title: "Verify neighbors", command: "show ip ospf neighbor", why: "Confirm that OSPF adjacency formed." }] },
  { id: 4, code: "LAB 04", title: "Services + Management", domain: "IP Services", blurb: "Make the network usable: provide addresses, resolve names, synchronize time, translate traffic, and manage devices securely.", topology: "Edge router · services VLAN · upstream provider", skills: ["DHCP relay", "NAT/PAT", "NTP", "SSH"], steps: [{ title: "Configure a DHCP pool", command: "ip dhcp pool USERS", why: "Define the address service for a client network." }, { title: "Configure NAT overload", command: "ip nat inside source list 1 interface g0/1 overload", why: "Translate many inside clients through one outside address." }, { title: "Set an NTP server", command: "ntp server 192.0.2.10", why: "Keep device clocks aligned for logs and operations." }, { title: "Enable SSH", command: "transport input ssh", why: "Restrict remote VTY access to encrypted management sessions." }] },
  { id: 5, code: "LAB 05", title: "Security + Troubleshooting", domain: "Security + Automation", blurb: "Harden access, filter traffic, protect Layer 2, diagnose a multi-symptom outage, and interpret a small REST/JSON workflow.", topology: "Campus edge · user/server/WLAN segments · controller", skills: ["ACLs", "Port security", "DHCP snooping", "REST + JSON"], steps: [{ title: "Secure privileged access", command: "enable secret STRONG_SECRET", why: "Protect privileged EXEC access with a hashed secret." }, { title: "Apply an ACL", command: "ip access-group 101 in", why: "Attach a traffic policy to an interface direction." }, { title: "Enable port security", command: "switchport port-security", why: "Limit which source MAC addresses can use an access port." }, { title: "Inspect the fault", command: "show logging", why: "Correlate syslog evidence with the outage symptoms." }] },
];

function LabSelector({ selectedLab, onSelect }: { selectedLab: number; onSelect: (id: number) => void }) {
  return <div className="border-b border-white/10 bg-[#0d151e] px-5 py-3 lg:px-8"><div className="mx-auto flex max-w-[1500px] items-center gap-2 overflow-x-auto"><span className="mr-2 shrink-0 font-mono text-[10px] uppercase tracking-[.16em] text-[#667780]">Curriculum</span>{curriculumLabs.map((item) => <button key={item.id} onClick={() => onSelect(item.id)} className={`flex shrink-0 items-center gap-2 rounded-lg border px-3 py-2 text-left transition ${selectedLab === item.id ? "border-[#63e6e2]/40 bg-[#173038] text-white" : "border-white/10 bg-[#101923] text-[#7f9098] hover:border-white/20 hover:text-white"}`}><span className={`font-mono text-[10px] ${selectedLab === item.id ? "text-[#63e6e2]" : "text-[#53636c]"}`}>{item.code}</span><span className="text-xs">{item.title}</span>{item.id === 1 && <span className="rounded bg-[#f5b74b]/10 px-1.5 py-0.5 font-mono text-[9px] text-[#f5b74b]">LIVE</span>}</button>)}</div></div>;
}

function initialDevice(name: DeviceName): DeviceState {
  return { mode: "user", context: null, forwarding: false, interfaces: { "g0/0": { up: false }, loopback0: { up: false } }, routes: [], history: ["Cisco IOS Software, IPv6 Lab Simulator", "Press Enter to submit a command. Tab completion is intentionally simplified.", ""] };
}
function initialLab(): LabState { return { activeDevice: "R1", verified: false, devices: { R1: initialDevice("R1"), R2: initialDevice("R2") } }; }
function cloneLab(lab: LabState): LabState {
  return { ...lab, devices: { R1: { ...lab.devices.R1, interfaces: { "g0/0": { ...lab.devices.R1.interfaces["g0/0"] }, loopback0: { ...lab.devices.R1.interfaces.loopback0 } }, routes: [...lab.devices.R1.routes], history: [...lab.devices.R1.history] }, R2: { ...lab.devices.R2, interfaces: { "g0/0": { ...lab.devices.R2.interfaces["g0/0"] }, loopback0: { ...lab.devices.R2.interfaces.loopback0 } }, routes: [...lab.devices.R2.routes], history: [...lab.devices.R2.history] } } };
}
function promptFor(device: DeviceState, name: DeviceName) {
  if (device.mode === "user") return `${name}>`;
  if (device.mode === "privileged") return `${name}#`;
  if (device.mode === "config") return `${name}(config)#`;
  return `${name}(config-if)#`;
}
function normalized(value: string) { return value.trim().toLowerCase().replace(/\s+/g, " "); }
function interfaceLabel(context: InterfaceName) { return context === "loopback0" ? "Loopback0" : "GigabitEthernet0/0"; }

function getCompletion(lab: LabState) {
  const r1 = lab.devices.R1; const r2 = lab.devices.R2;
  const r1Transit = Boolean(r1.interfaces["g0/0"].global && r1.interfaces["g0/0"].linkLocal && r1.interfaces["g0/0"].up);
  const r2Transit = Boolean(r2.interfaces["g0/0"].global && r2.interfaces["g0/0"].linkLocal && r2.interfaces["g0/0"].up);
  const r1Loop = Boolean(r1.interfaces.loopback0.global && r1.interfaces.loopback0.up);
  const r2Loop = Boolean(r2.interfaces.loopback0.global && r2.interfaces.loopback0.up);
  const bothRoutes = r1.routes.includes("2001:db8:2::/64") && r2.routes.includes("2001:db8:1::/64");
  return [r1.mode !== "user", r1.forwarding, r1Transit, r1Loop, r2.forwarding && r2Transit && r2Loop, bothRoutes, lab.verified];
}
function suggestedCommand(lab: LabState, stepId: number): { device: DeviceName; command: string } {
  const deviceName: DeviceName = stepId <= 4 ? "R1" : stepId === 5 ? "R2" : lab.activeDevice;
  const d = lab.devices[deviceName];
  if (stepId === 6) {
    const targetName: DeviceName = !lab.devices.R1.routes.includes("2001:db8:2::/64") ? "R1" : "R2";
    const target = lab.devices[targetName];
    const route = targetName === "R1" ? "ipv6 route 2001:db8:2::/64 fe80::2 g0/0" : "ipv6 route 2001:db8:1::/64 fe80::1 g0/0";
    if (target.mode === "user") return { device: targetName, command: "enable" };
    if (target.mode === "privileged") return { device: targetName, command: "configure terminal" };
    return { device: targetName, command: route };
  }
  if (stepId === 7) {
    const r1 = lab.devices.R1;
    return { device: "R1", command: r1.mode === "privileged" ? "ping ipv6 2001:db8:2::1" : r1.mode === "config" || r1.mode === "interface" ? "end" : "enable" };
  }
  if (d.mode === "user") return { device: deviceName, command: "enable" };
  if (d.mode === "privileged") return { device: deviceName, command: "configure terminal" };
  if (!d.forwarding && (stepId === 2 || stepId === 5)) return { device: deviceName, command: "ipv6 unicast-routing" };
  if (stepId === 3) { const i = d.interfaces["g0/0"]; if (d.mode !== "interface" || d.context !== "g0/0") return { device: deviceName, command: "interface g0/0" }; if (!i.global) return { device: deviceName, command: `ipv6 address 2001:db8:12:12::${deviceName === "R1" ? "1" : "2"}/64` }; if (!i.linkLocal) return { device: deviceName, command: `ipv6 address fe80::${deviceName === "R1" ? "1" : "2"} link-local` }; if (!i.up) return { device: deviceName, command: "no shutdown" }; }
  if (stepId === 4) { const i = d.interfaces.loopback0; if (d.mode !== "interface" || d.context !== "loopback0") return { device: deviceName, command: "interface loopback 0" }; if (!i.global) return { device: deviceName, command: "ipv6 address 2001:db8:1::1/64" }; if (!i.up) return { device: deviceName, command: "no shutdown" }; }
  if (stepId === 5) { const i = d.interfaces["g0/0"]; if (d.mode !== "interface" || d.context !== "g0/0") return { device: deviceName, command: "interface g0/0" }; if (!i.global) return { device: deviceName, command: "ipv6 address 2001:db8:12:12::2/64" }; if (!i.linkLocal) return { device: deviceName, command: "ipv6 address fe80::2 link-local" }; if (!i.up) return { device: deviceName, command: "no shutdown" }; if (!d.interfaces.loopback0.global) return { device: deviceName, command: "interface loopback 0" }; if (!d.interfaces.loopback0.up) return { device: deviceName, command: "no shutdown" }; }
  return { device: deviceName, command: "show ipv6 route" };
}

function Lab2Simulator() {
  type SimDevice = "R1" | "SW1" | "SW2";
  type SimMode = "user" | "privileged" | "config" | "vlan" | "interface" | "range" | "subinterface";
  type DeviceState = { mode: SimMode; context: string | null; history: string[]; vlans: Set<string>; accessPorts: Set<string>; trunks: Set<string>; etherchannel: boolean; routerAddresses: Set<string>; rapidPvst: boolean };
  type SimState = { active: SimDevice; devices: Record<SimDevice, DeviceState> };
  const boot = (device: SimDevice): DeviceState => ({ mode: "user", context: null, history: ["Cisco IOS Software, CCNA Lab Simulator", device === "R1" ? "Construction Enterprises HQ edge router" : `${device} · Construction Enterprises Factory to Foundation access switch`, "Type full Cisco IOS commands. Use ? only as a learning prompt."], vlans: new Set(), accessPorts: new Set(), trunks: new Set(), etherchannel: false, routerAddresses: new Set(), rapidPvst: false });
  const [sim, setSim] = useState<SimState>(() => ({ active: "SW1", devices: { R1: boot("R1"), SW1: boot("SW1"), SW2: boot("SW2") } }));
  const [input, setInput] = useState("");
  const [hint, setHint] = useState(false);
  const device = sim.devices[sim.active];
  const allDevices = [sim.devices.SW1, sim.devices.SW2];
  const flags = { vlans: allDevices.every((current) => ["10", "20", "99", "999"].every((v) => current.vlans.has(v))), access: sim.devices.SW1.accessPorts.size > 0 && sim.devices.SW2.accessPorts.size > 0, etherchannel: sim.devices.SW1.etherchannel && sim.devices.SW2.etherchannel, router: sim.devices.R1.routerAddresses.size >= 3, ping: sim.devices.R1.routerAddresses.size >= 3 && sim.devices.SW1.etherchannel && sim.devices.SW2.etherchannel };
  const tasks = [{ label: "Create Construction VLANs 10 / 20 / 99 / 999", done: flags.vlans }, { label: "Assign Factory access ports", done: flags.access }, { label: "Build LACP trunk to Headquarters", done: flags.etherchannel }, { label: "Configure HQ router subinterfaces", done: flags.router }, { label: "Verify Factory-to-HQ inter-VLAN reachability", done: flags.ping }];
  const doneCount = tasks.filter((task) => task.done).length;
  const prompt = device.mode === "user" ? `${sim.active}>` : device.mode === "privileged" ? `${sim.active}#` : device.mode === "config" ? `${sim.active}(config)#` : device.mode === "vlan" ? `${sim.active}(config-vlan)#` : device.mode === "range" ? `${sim.active}(config-if-range)#` : device.mode === "subinterface" ? `${sim.active}(config-subif)#` : `${sim.active}(config-if)#`;
  const activeTask = tasks.find((task) => !task.done) ?? tasks[tasks.length - 1];

  function updateDevice(mutator: (next: DeviceState) => void, lines: string[] = []) {
    setSim((current) => { const nextDevice = { ...current.devices[current.active], history: [...current.devices[current.active].history] }; mutator(nextDevice); nextDevice.history.push(...lines); return { ...current, devices: { ...current.devices, [current.active]: nextDevice } }; });
  }
  function switchDevice(next: SimDevice) { setSim((current) => ({ ...current, active: next })); setInput(""); setHint(false); }
  function appendCommand(value: string) { setSim((current) => { const nextDevice = { ...current.devices[current.active], history: [...current.devices[current.active].history, `${prompt} ${value}`] }; return { ...current, devices: { ...current.devices, [current.active]: nextDevice } }; }); }
  function fail(message: string) { updateDevice((next) => {}, ["% Invalid input detected at '^' marker.", `Hint: ${message}`]); }
  function submit(value = input) {
    const raw = value.trim(); const cmd = raw.toLowerCase().replace(/\s+/g, " "); if (!cmd) return;
    appendCommand(raw);
    const state = sim.devices[sim.active];
    if (cmd === "enable") { if (state.mode !== "user") fail("You are already beyond user EXEC mode."); else updateDevice((next) => { next.mode = "privileged"; }, [`${sim.active} is now in privileged EXEC mode.`]); }
    else if (cmd === "configure terminal" || cmd === "conf t") { if (state.mode !== "privileged") fail("Use enable first, then configure terminal."); else updateDevice((next) => { next.mode = "config"; }, ["Enter configuration commands, one per line. End with CNTL/Z."]); }
    else if (cmd === "end") updateDevice((next) => { next.mode = "privileged"; next.context = null; }, ["Returned to privileged EXEC mode."]);
    else if (cmd === "exit") { if (["vlan", "interface", "range", "subinterface"].includes(state.mode)) updateDevice((next) => { next.mode = "config"; next.context = null; }, ["Returned to global configuration mode."]); else if (state.mode === "config") updateDevice((next) => { next.mode = "privileged"; }, ["Returned to privileged EXEC mode."]); else fail("Exit configuration mode only after entering it."); }
    else if (cmd.startsWith("vlan ")) { const vlan = cmd.slice(5); if (state.mode !== "config") fail("Create VLANs from SW1(config)# or SW2(config)#."); else if (["10", "20", "99", "999"].includes(vlan)) updateDevice((next) => { next.mode = "vlan"; next.context = vlan; next.vlans.add(vlan); }, [`Entering VLAN configuration for VLAN ${vlan}.`]); else fail("Use VLAN 10, 20, 99, or 999 for this lab."); }
    else if (cmd.startsWith("name ")) { if (state.mode !== "vlan") fail("Enter vlan <number> first; the prompt should be (config-vlan)#."); else updateDevice((next) => {}, [`VLAN ${state.context} name set to ${raw.slice(5)}.`]); }
    else if (cmd === "interface fa0/1" || cmd === "int fa0/1") { if (state.mode !== "config") fail("Select the Factory access port from global configuration mode."); else updateDevice((next) => { next.mode = "interface"; next.context = "fa0/1"; }, ["Interface FastEthernet0/1 selected."]); }
    else if (cmd === "interface g0/1" || cmd === "int g0/1") { if (state.mode !== "config") fail("Select the Headquarters uplink from global configuration mode."); else updateDevice((next) => { next.mode = "interface"; next.context = "g0/1"; }, ["Interface GigabitEthernet0/1 selected."]); }
    else if (cmd === "interface range g0/2 - 3" || cmd === "int range g0/2 - 3") { if (state.mode !== "config") fail("Select the two Factory-to-Foundation links from global configuration mode."); else updateDevice((next) => { next.mode = "range"; next.context = "g0/2 - 3"; }, ["Interface range GigabitEthernet0/2 - 3 selected."]); }
    else if (cmd === "interface port-channel 1" || cmd === "int po1") { if (state.mode !== "config") fail("Select Port-channel1 from global configuration mode."); else updateDevice((next) => { next.mode = "interface"; next.context = "port-channel1"; }, ["Interface Port-channel1 selected."]); }
    else if (cmd.startsWith("interface g0/0.")) { if (sim.active !== "R1" || state.mode !== "config") fail("On R1, select a subinterface from global configuration mode."); else updateDevice((next) => { next.mode = "subinterface"; next.context = cmd.slice(13); }, [`Interface GigabitEthernet0/0.${cmd.slice(13)} selected.`]); }
    else if (cmd === "interface g0/0" || cmd === "int g0/0") { if (sim.active !== "R1" || state.mode !== "config") fail("On R1, select G0/0 from global configuration mode."); else updateDevice((next) => { next.mode = "interface"; next.context = "g0/0"; }, ["Interface GigabitEthernet0/0 selected."]); }
    else if (cmd === "switchport mode access") { if (state.mode !== "interface") fail("Select an access interface first."); else updateDevice((next) => { next.accessPorts.add(next.context ?? "fa0/1"); }, ["Switchport mode set to access."]); }
    else if (cmd.startsWith("switchport access vlan ")) { if (state.mode !== "interface") fail("Select the Factory access port first."); else updateDevice((next) => { next.accessPorts.add(`${next.context ?? "fa0/1"} VLAN ${cmd.slice(23)}`); }, [`Access VLAN ${cmd.slice(23)} assigned.`]); }
    else if (cmd === "switchport mode trunk") { if (!["interface", "range"].includes(state.mode)) fail("Select the Headquarters uplink, member range, or Port-channel first."); else updateDevice((next) => { next.trunks.add(next.context ?? "trunk"); }, ["Switchport mode set to trunk."]); }
    else if (cmd === "switchport trunk native vlan 999") { if (!["interface", "range"].includes(state.mode)) fail("Apply the native VLAN from trunk interface mode."); else updateDevice((next) => {}, ["Native VLAN set to 999."]); }
    else if (cmd === "switchport trunk allowed vlan 10,20,99,999") { if (!["interface", "range"].includes(state.mode)) fail("Apply the allowed VLAN list from trunk interface mode."); else updateDevice((next) => {}, ["Allowed VLAN list set to 10,20,99,999."]); }
    else if (cmd === "channel-group 1 mode active") { if (state.mode !== "range") fail("Enter interface range g0/2 - 3 before creating the LACP bundle."); else updateDevice((next) => { next.etherchannel = true; }, ["LACP channel-group 1 configured in active mode.", "Port-channel1 will form when the peer matches."]); }
    else if (cmd === "spanning-tree mode rapid-pvst") { if (state.mode !== "config") fail("Configure Rapid PVST+ from global configuration mode."); else updateDevice((next) => { next.rapidPvst = true; }, ["Spanning-tree mode set to rapid-pvst."]); }
    else if (cmd.includes("spanning-tree vlan") && (cmd.endsWith("root primary") || cmd.endsWith("root secondary"))) { if (state.mode !== "config") fail("Configure the STP root role from global configuration mode."); else updateDevice((next) => {}, [`Rapid PVST+ root role accepted for ${sim.active}.`]); }
    else if (cmd.startsWith("encapsulation dot1q ")) { if (sim.active !== "R1" || state.mode !== "subinterface") fail("Select R1 G0/0.<vlan> before applying 802.1Q encapsulation."); else updateDevice((next) => {}, ["802.1Q encapsulation applied to the subinterface."]); }
    else if (cmd.startsWith("ip address 192.168.") || cmd.startsWith("ipv6 address 2001:db8:")) { if (sim.active !== "R1" || state.mode !== "subinterface") fail("Select an R1 router subinterface before assigning a gateway address."); else updateDevice((next) => { next.routerAddresses.add(`${next.context ?? "subinterface"}:${cmd}`); }, ["Gateway address applied to the subinterface."]); }
    else if (cmd === "no shutdown") { if (!["interface", "range", "subinterface"].includes(state.mode)) fail("Select an interface before using no shutdown."); else updateDevice((next) => {}, ["Interface enabled."]); }
    else if (cmd === "show vlan brief" || cmd === "show interfaces trunk" || cmd === "show etherchannel summary" || cmd === "show spanning-tree" || cmd === "show mac address-table" || cmd === "show ip interface brief" || cmd === "show ipv6 interface brief" || cmd === "show ip route") { if (state.mode !== "privileged") fail("Use end before running show commands."); else updateDevice((next) => {}, ["Verification output:", sim.active === "SW1" ? "VLAN 10 USERS-A · VLAN 20 USERS-B · VLAN 99 MANAGEMENT · VLAN 999 NATIVE-UNUSED" : `${sim.active}: command accepted; inspect the named Construction Enterprises topology.`]); }
    else if (cmd === "ping 192.168.20.10" || cmd === "ping ipv6 2001:db8:20::10") { if (sim.active !== "R1" || state.mode !== "privileged") fail("Run the Factory-to-Foundation reachability test from R1#."); else if (flags.router && flags.etherchannel) updateDevice((next) => {}, ["Type escape sequence to abort.", "!!!!!", "Success rate is 100 percent (5/5)", "✓ Evidence: Factory-to-Foundation inter-VLAN reachability confirmed."]); else updateDevice((next) => {}, [".....", "Success rate is 0 percent (0/5)", "% Check the full VLAN, trunk, EtherChannel, and subinterface sequence."]); }
    else if (cmd === "?" || cmd === "show ?") updateDevice((next) => {}, ["Available commands: enable · configure terminal · interface · vlan · switchport · channel-group · spanning-tree · encapsulation · ip address · ipv6 address · show · ping"]);
    else fail("Use the full command for the current IOS mode. Abbreviations are not used in this lab.");
    setInput(""); setHint(false);
  }
  function runSuggested() { const state = sim.devices[sim.active]; let target: SimDevice = sim.active; let cmd = "enable"; if (activeTask.label.startsWith("Create")) { const missingVlan = ["10", "20", "99", "999"].find((v) => !state.vlans.has(v)) ?? "10"; cmd = state.mode === "user" ? "enable" : state.mode === "privileged" ? "configure terminal" : state.mode === "config" ? `vlan ${missingVlan}` : `name ${missingVlan === "10" ? "CE-HQ-ENGINEERING" : missingVlan === "20" ? "FTF-PRODUCTION" : missingVlan === "99" ? "CE-NET-MANAGEMENT" : "CE-NATIVE-BLACKHOLE"}`; } else if (activeTask.label.startsWith("Assign")) cmd = state.mode === "user" ? "enable" : state.mode === "privileged" ? "configure terminal" : state.mode === "config" ? "interface fa0/1" : "switchport mode access"; else if (activeTask.label.startsWith("Build")) cmd = state.mode === "user" ? "enable" : state.mode === "privileged" ? "configure terminal" : state.mode === "config" ? "interface range g0/2 - 3" : state.mode === "range" ? "channel-group 1 mode active" : "switchport mode trunk"; else if (activeTask.label.startsWith("Configure")) { target = "R1"; cmd = state.mode === "user" ? "enable" : state.mode === "privileged" ? "configure terminal" : state.mode === "config" ? "interface g0/0.10" : state.mode === "subinterface" ? "encapsulation dot1q 10" : "ipv6 unicast-routing"; } else { target = "R1"; cmd = state.mode === "user" ? "enable" : state.mode === "privileged" ? "ping 192.168.20.10" : "end"; } if (target !== sim.active) { switchDevice(target); setInput(cmd); } else submit(cmd); }
  function reset() { setSim({ active: "SW1", devices: { R1: boot("R1"), SW1: boot("SW1"), SW2: boot("SW2") } }); setInput(""); setHint(false); }
  return <div className="relative min-h-screen bg-[#0b1118] text-[#f2f5f5]"><div className="mx-auto max-w-[1500px] px-5 py-7 lg:px-10"><div className="mb-6 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="instrument-label text-[#f5b74b]">LAB 02 · NETWORK ACCESS · CONSTRUCTION ENTERPRISES</div><h1 className="mt-2 font-display text-3xl font-semibold tracking-[-.03em] text-white md:text-5xl">Switch the network.<br /><span className="text-[#63e6e2]">Route the business.</span></h1><p className="mt-3 max-w-2xl text-sm leading-6 text-[#aebbc0]">Build the Factory to Foundation campus path with full Cisco IOS modes and command sequences. No shortcuts: read the prompt, enter the command, verify the evidence.</p></div><Button variant="outline" className="border-white/15 bg-[#101923]/70 text-[#aab8bd] hover:bg-white/10 hover:text-white" onClick={reset}><RotateCcw className="mr-2 h-4 w-4" /> Reset Lab 2</Button></div><div className="grid gap-6 xl:grid-cols-[.72fr_1.28fr]"><div className="space-y-6"><section className="panel-surface overflow-hidden"><div className="flex items-center justify-between border-b border-white/10 px-5 py-4"><div><div className="instrument-label">CONSTRUCTION ENTERPRISES · DEVICE RACK</div><div className="mt-1 text-sm text-[#aab8bd]">Factory to Foundation campus</div></div><span className="status-pill"><span className="status-dot" /> {doneCount}/5 CHECKS</span></div><div className="p-5"><div className="grid grid-cols-3 gap-2">{(["SW1", "SW2", "R1"] as SimDevice[]).map((name) => <button key={name} onClick={() => switchDevice(name)} className={`rounded-lg border px-3 py-4 text-left transition ${sim.active === name ? "border-[#63e6e2]/50 bg-[#173038]" : "border-white/10 bg-[#0e1720] hover:border-white/20"}`}><div className="font-mono text-sm text-[#63e6e2]">{name}</div><div className="mt-1 text-[10px] uppercase tracking-wider text-[#70818a]">{name === "R1" ? "HQ edge router" : name === "SW1" ? "HQ distribution" : "Factory access"}</div></button>)}</div><div className="mt-5 rounded-xl border border-white/10 bg-[#0e1720] p-5"><div className="instrument-label">FACTORY TO FOUNDATION TOPOLOGY</div><div className="mt-5 flex items-center justify-between font-mono text-center text-xs"><div><div className="rounded-lg border border-[#63e6e2]/40 bg-[#173038] px-3 py-3 text-[#63e6e2]">HQ</div><div className="mt-2 text-[9px] text-[#72838b]">SW1 · VLAN 10</div></div><div className="h-px flex-1 bg-[#385159]" /><div><div className="rounded-lg border border-[#f5b74b]/40 bg-[#302717] px-3 py-3 text-[#f5b74b]">R1</div><div className="mt-2 text-[9px] text-[#72838b]">VLAN gateways</div></div><div className="h-px flex-1 bg-[#385159]" /><div><div className="rounded-lg border border-[#f5b74b]/40 bg-[#302717] px-3 py-3 text-[#f5b74b]">Factory</div><div className="mt-2 text-[9px] text-[#72838b]">SW2 · VLAN 20</div></div></div></div></div></section><section className="panel-surface"><div className="border-b border-white/10 px-5 py-4"><div className="instrument-label">MISSION CHECKLIST</div><div className="mt-1 text-sm text-[#aab8bd]">Follow the full IOS sequence in order</div></div><div className="space-y-1 p-4">{tasks.map((task, index) => <div key={task.label} className={`flex items-center gap-3 rounded-lg px-3 py-3 ${task.done ? "bg-[#12302d]/60" : index === tasks.findIndex((item) => !item.done) ? "bg-[#302717]/70" : "bg-transparent"}`}><span className={`font-mono text-[10px] ${task.done ? "text-[#63e6e2]" : "text-[#f5b74b]"}`}>0{index + 1}</span>{task.done ? <Check className="h-4 w-4 text-[#63e6e2]" /> : <span className="h-4 w-4 rounded-full border border-[#63727a]" />}<span className={`text-sm ${task.done ? "text-[#b5d8d4]" : "text-[#aebbc0]"}`}>{task.label}</span></div>)}</div></section></div><section className="terminal-shell"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/10 bg-[#111b24] px-5 py-3"><div className="flex items-center gap-2"><div className="flex gap-1.5"><span className="h-2.5 w-2.5 rounded-full bg-[#f07178]" /><span className="h-2.5 w-2.5 rounded-full bg-[#f5b74b]" /><span className="h-2.5 w-2.5 rounded-full bg-[#63e6e2]" /></div><span className="ml-2 font-mono text-[10px] uppercase tracking-[.18em] text-[#74848d]">ios-sim / {sim.active}</span></div><div className="font-mono text-[10px] uppercase tracking-wider text-[#667780]">{prompt}</div></div><div className="terminal-output" aria-live="polite">{device.history.map((line, index) => <div key={`${line}-${index}`} className={`${line.startsWith("%") ? "text-[#f07178]" : line.startsWith("✓") ? "text-[#f5b74b]" : line.startsWith("Cisco") || line.startsWith("Construction") || line.startsWith("Type") ? "text-[#72848d]" : line.startsWith("SW") || line.startsWith("R1") ? "text-[#c8d4d7]" : "text-[#9aaab0]"}`}>{line || "\u00a0"}</div>)}<div className="mt-3 flex items-center gap-2"><span className="text-[#63e6e2]">{prompt}</span><input autoFocus value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => event.key === "Enter" && submit()} className="min-w-0 flex-1 bg-transparent font-mono text-sm text-white outline-none placeholder:text-[#42535c]" placeholder="type full Cisco IOS command..." aria-label="Cisco IOS command" /></div></div><div className="border-t border-white/10 bg-[#0e1720] px-5 py-3"><div className="mb-3 flex items-start gap-2 rounded-lg border border-[#f5b74b]/20 bg-[#f5b74b]/10 p-3 text-xs leading-5 text-[#f3d590]"><CircleHelp className="mt-0.5 h-4 w-4 shrink-0" /><div><strong className="font-medium">Current objective:</strong> {activeTask.label}. {hint ? "Use the exact command sequence below; the prompt determines which command is valid." : "Type full commands manually. Use Need a nudge? only if you need a reminder."}</div></div><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex gap-2"><Button variant="outline" size="sm" className="border-white/15 bg-transparent text-[#94a4aa] hover:bg-white/10 hover:text-white" onClick={() => setHint((value) => !value)}><CircleHelp className="mr-2 h-3.5 w-3.5" /> {hint ? "Hide hint" : "Need a nudge?"}</Button><Button variant="outline" size="sm" className="border-white/15 bg-transparent text-[#94a4aa] hover:bg-white/10 hover:text-white" onClick={() => { navigator.clipboard?.writeText(activeTask.label); toast("Objective copied"); }}><Copy className="mr-2 h-3.5 w-3.5" /> Copy objective</Button></div><Button size="sm" className="bg-[#f5b74b] text-[#1c160b] hover:bg-[#ffca69]" onClick={runSuggested}><Play className="mr-2 h-3.5 w-3.5" /> Run suggested</Button></div></div></section></div><div className="mt-6 border-t border-white/10 pt-5 text-xs text-[#687780]">Full IOS mode practice · Construction Enterprises Headquarters ↔ Factory to Foundation · Simulated entirely in the browser.</div></div></div>;
}

export default function Home() {
  const [lab, setLab] = useState<LabState>(() => initialLab());
  const [selectedLab, setSelectedLab] = useState(1);
  const selectedCurriculum = curriculumLabs[selectedLab - 1];
  const [command, setCommand] = useState("");
  const [hintVisible, setHintVisible] = useState(false);
  const [showGuide, setShowGuide] = useState(true);
  const completion = getCompletion(lab);
  const completedCount = completion.filter(Boolean).length;
  const activeStep = Math.min(completion.findIndex((done) => !done) + 1 || steps.length, steps.length);
  const step = steps[activeStep - 1];
  const device = lab.devices[lab.activeDevice];
  const prompt = promptFor(device, lab.activeDevice);
  const percent = Math.round((completedCount / steps.length) * 100);
  const statusLabel = completedCount === steps.length ? "LAB COMPLETE" : `STEP ${String(activeStep).padStart(2, "0")} OF ${String(steps.length).padStart(2, "0")}`;

  function switchDevice(next: DeviceName) { setLab((current) => ({ ...current, activeDevice: next })); setCommand(""); setHintVisible(false); toast(`Console switched to ${next}`, { description: "The simulator is ready for the next command." }); }

  function submitCommand(value = command) {
    const text = value.trim(); if (!text) return;
    const next = cloneLab(lab); const d = next.devices[next.activeDevice]; const name = next.activeDevice; const beforePrompt = promptFor(d, name); const cmd = normalized(text); d.history.push(`${beforePrompt} ${text}`);
    let response: string[] = []; let valid = true;
    const add = (...lines: string[]) => { response = [...response, ...lines]; };
    const invalid = (hint = step.hint) => { valid = false; add("% Invalid input detected at '^' marker.", `Hint: ${hint}`); };

    if (cmd === "enable") { if (d.mode !== "user") invalid("You are already in privileged or configuration mode."); else { d.mode = "privileged"; add(`${name} is now in privileged EXEC mode.`, "✓ Evidence: The # prompt indicates privileged EXEC mode."); } }
    else if (cmd === "configure terminal" || cmd === "conf t") { if (d.mode !== "privileged") invalid("Use enable first, then configure terminal."); else { d.mode = "config"; add("Enter configuration commands, one per line. End with CNTL/Z."); } }
    else if (cmd === "end") { if (d.mode === "user") invalid("Use enable before leaving configuration mode."); else { d.mode = "privileged"; d.context = null; add("Returned to privileged EXEC mode."); } }
    else if (cmd === "exit") { if (d.mode === "interface") { d.mode = "config"; d.context = null; add("Returned to global configuration mode."); } else if (d.mode === "config") { d.mode = "privileged"; add("Returned to privileged EXEC mode."); } else invalid("There is no configuration context to exit from."); }
    else if (cmd === "ipv6 unicast-routing") { if (d.mode !== "config") invalid("Enter configure terminal mode before enabling IPv6 forwarding."); else { d.forwarding = true; add("IPv6 unicast forwarding enabled.", "✓ Evidence: IPv6 forwarding is a global router setting."); } }
    else if (cmd === "interface g0/0" || cmd === "int g0/0" || cmd === "interface gigabitethernet 0/0" || cmd === "int gigabitethernet 0/0") { if (d.mode !== "config") invalid("Enter configure terminal before selecting an interface."); else { d.mode = "interface"; d.context = "g0/0"; add(`Interface ${interfaceLabel("g0/0")} selected.`); } }
    else if (cmd === "interface loopback 0" || cmd === "int loopback 0" || cmd === "interface lo0" || cmd === "int lo0") { if (d.mode !== "config") invalid("Enter configure terminal before selecting a loopback."); else { d.mode = "interface"; d.context = "loopback0"; add("Interface Loopback0 selected."); } }
    else if (cmd.startsWith("ipv6 address ")) {
      if (d.mode !== "interface" || !d.context) invalid("Select G0/0 or Loopback0 before assigning an address.");
      else if (cmd.includes("fe80::1") && name === "R1" && cmd.endsWith("link-local")) { d.interfaces["g0/0"].linkLocal = "fe80::1"; add("Link-local address fe80::1 applied to G0/0."); }
      else if (cmd.includes("fe80::2") && name === "R2" && cmd.endsWith("link-local")) { d.interfaces["g0/0"].linkLocal = "fe80::2"; add("Link-local address fe80::2 applied to G0/0."); }
      else if (d.context === "g0/0" && ((name === "R1" && cmd.includes("2001:db8:12:12::1/64")) || (name === "R2" && cmd.includes("2001:db8:12:12::2/64")))) { d.interfaces["g0/0"].global = name === "R1" ? "2001:db8:12:12::1/64" : "2001:db8:12:12::2/64"; add(`Global IPv6 address applied to ${interfaceLabel("g0/0")}.`); }
      else if (d.context === "loopback0" && name === "R1" && cmd.includes("2001:db8:1::1/64")) { d.interfaces.loopback0.global = "2001:db8:1::1/64"; add("Global IPv6 address applied to Loopback0."); }
      else if (d.context === "loopback0" && name === "R2" && cmd.includes("2001:db8:2::1/64")) { d.interfaces.loopback0.global = "2001:db8:2::1/64"; add("Global IPv6 address applied to Loopback0."); }
      else invalid("Use the IPv6 address shown in the addressing plan for the selected interface.");
    }
    else if (cmd === "no shutdown") { if (d.mode !== "interface" || !d.context) invalid("Select an interface before using no shutdown."); else { d.interfaces[d.context].up = true; add(`%LINK-5-CHANGED: Interface ${interfaceLabel(d.context)}, changed state to up`, `✓ Evidence: ${interfaceLabel(d.context)} is administratively enabled.`); } }
    else if (cmd.startsWith("ipv6 route ")) {
      if (d.mode !== "config") invalid("Enter global configuration mode before adding a route.");
      else if (name === "R1" && cmd.includes("2001:db8:2::/64") && cmd.includes("fe80::2") && cmd.includes("g0/0")) { if (!d.routes.includes("2001:db8:2::/64")) d.routes.push("2001:db8:2::/64"); add("Static route to 2001:db8:2::/64 installed."); }
      else if (name === "R2" && cmd.includes("2001:db8:1::/64") && cmd.includes("fe80::1") && cmd.includes("g0/0")) { if (!d.routes.includes("2001:db8:1::/64")) d.routes.push("2001:db8:1::/64"); add("Static route to 2001:db8:1::/64 installed."); }
      else invalid("Use the remote loopback prefix, the neighbor link-local address, and g0/0.");
    }
    else if (cmd === "show ipv6 interface brief") { if (d.mode !== "privileged") invalid("Use end to return to privileged EXEC mode before show commands."); else { add(`${name}# show ipv6 interface brief`, `${d.interfaces["g0/0"].up ? "GigabitEthernet0/0     up/up" : "GigabitEthernet0/0     administratively down"}   ${d.interfaces["g0/0"].global ?? "unassigned"}`, `${d.interfaces.loopback0.up ? "Loopback0             up/up" : "Loopback0             down/down"}   ${d.interfaces.loopback0.global ?? "unassigned"}`); } }
    else if (cmd === "show ipv6 route") { if (d.mode !== "privileged") invalid("Use end to return to privileged EXEC mode before show commands."); else { add(`${name}# show ipv6 route`, `C   ${name === "R1" ? "2001:DB8:1::/64" : "2001:DB8:2::/64"} is directly connected, Loopback0`, "C   2001:DB8:12:12::/64 is directly connected, GigabitEthernet0/0", ...(d.routes.length ? d.routes.map((route) => `S   ${route.toUpperCase()} [1/0]`) : ["% No static IPv6 routes configured"])); } }
    else if (cmd === "show ipv6 neighbors") { if (d.mode !== "privileged") invalid("Use end to return to privileged EXEC mode before show commands."); else if (lab.devices.R1.interfaces["g0/0"].up && lab.devices.R2.interfaces["g0/0"].up) add(`${name}# show ipv6 neighbors`, `${name === "R1" ? "FE80::2" : "FE80::1"}  ${name === "R1" ? "2001:DB8:12:12::2" : "2001:DB8:12:12::1"}  G0/0  STALE`); else add(`${name}# show ipv6 neighbors`, "% No IPv6 neighbors discovered yet."); }
    else if (cmd === "ping ipv6 2001:db8:12:12::2" || cmd === "ping ipv6 2001:db8:12:12::1" || cmd.startsWith("ping ipv6 fe80::2") || cmd.startsWith("ping ipv6 fe80::1")) {
      const targetIsCorrect = (name === "R1" && cmd.includes("::2")) || (name === "R2" && cmd.includes("::1"));
      if (d.mode !== "privileged") invalid("Use end to return to privileged EXEC mode before testing reachability.");
      else if (!targetIsCorrect) invalid(`From ${name}, ping the other router’s transit address.`);
      else if (lab.devices.R1.interfaces["g0/0"].up && lab.devices.R2.interfaces["g0/0"].up) add("Type escape sequence to abort.", `Sending 5, 100-byte ICMP Echos to ${name === "R1" ? "2001:DB8:12:12::2" : "2001:DB8:12:12::1"}, timeout is 2 seconds:`, "!!!!!", "Success rate is 100 percent (5/5)", "✓ Evidence: The directly connected IPv6 transit link is reachable.");
      else add("Type escape sequence to abort.", ".....", "Success rate is 0 percent (0/5)", "% Destination unreachable — inspect the transit interface state.");
    }
    else if (cmd === "ping ipv6 2001:db8:2::1") { if (d.mode !== "privileged") invalid("Use end to return to privileged EXEC mode before testing reachability."); else if (lab.devices.R1.routes.includes("2001:db8:2::/64") && lab.devices.R2.routes.includes("2001:db8:1::/64") && lab.devices.R1.interfaces["g0/0"].up && lab.devices.R2.interfaces["g0/0"].up) { next.verified = true; add("Type escape sequence to abort.", "Sending 5, 100-byte ICMP Echos to 2001:DB8:2::1, timeout is 2 seconds:", "!!!!!", "Success rate is 100 percent (5/5)", "✓ Evidence: End-to-end IPv6 reachability confirmed."); } else add("Type escape sequence to abort.", ".....", "Success rate is 0 percent (0/5)", "% Destination unreachable — inspect the routing table and interface state."); }
    else if (cmd === "ping ipv6 2001:db8:1::1") { if (d.mode !== "privileged") invalid("Use end to return to privileged EXEC mode before testing reachability."); else add("Type escape sequence to abort.", "!!!!!", "Success rate is 100 percent (5/5)"); }
    else invalid();

    d.history.push(...response);
    setLab(next); setCommand(""); setHintVisible(false);
    if (!valid) toast.error("That command cannot run in the current CLI context."); else toast.success("Command accepted", { description: "The simulator state has been updated." });
  }

  function runSuggested() {
    const suggestion = suggestedCommand(lab, activeStep);
    if (lab.activeDevice !== suggestion.device) {
      setLab((current) => ({ ...current, activeDevice: suggestion.device }));
      setCommand(suggestion.command);
      toast(`Console switched to ${suggestion.device}`, { description: "The suggested command is ready. Press Enter to run it." });
      return;
    }
    submitCommand(suggestion.command);
  }
  function resetLab() { setLab(initialLab()); setCommand(""); setHintVisible(false); toast("Lab reset", { description: "Both simulated routers returned to their initial state." }); }
  function copyHint() { navigator.clipboard?.writeText(step.hint); toast("Hint copied"); }

  if (selectedLab === 2) return <main className="min-h-screen overflow-hidden bg-[#0b1118] text-[#f2f5f5]"><header className="border-b border-white/10 bg-[#0b1118]/95 backdrop-blur-md"><div className="mx-auto flex max-w-[1500px] items-center justify-between px-5 py-4 lg:px-8"><div className="flex items-center gap-3"><div className="relative flex h-10 w-10 items-center justify-center overflow-hidden rounded-xl border border-[#63e6e2]/40 bg-[#10252b]"><img src="/manus-storage/ipv6-trace-mark_f814341b.png" alt="IPv6 CLI Lab mark" className="h-8 w-8 object-contain" /></div><div><div className="font-mono text-[11px] uppercase tracking-[.22em] text-[#63e6e2]">Packet Observatory</div><div className="font-display text-lg font-semibold tracking-tight">IPv6 CLI Lab</div></div></div><div className="font-mono text-[10px] uppercase tracking-wider text-[#667780]">TRAINING CONSOLE · LAB 02</div></div></header><LabSelector selectedLab={selectedLab} onSelect={(id) => { setSelectedLab(id); setHintVisible(false); }} /><Lab2Simulator /></main>;

  return <main className="min-h-screen overflow-hidden bg-[#0b1118] text-[#f2f5f5]">
    <header className="border-b border-white/10 bg-[#0b1118]/95 backdrop-blur-md"><div className="mx-auto flex max-w-[1500px] items-center justify-between px-5 py-4 lg:px-8"><div className="flex items-center gap-3"><div className="relative flex h-10 w-10 items-center justify-center overflow-hidden rounded-xl border border-[#63e6e2]/40 bg-[#10252b] shadow-[0_0_22px_rgba(99,230,226,.12)]"><img src="/manus-storage/ipv6-trace-mark_f814341b.png" alt="IPv6 CLI Lab mark" className="h-8 w-8 object-contain" /></div><div><div className="font-mono text-[11px] uppercase tracking-[.22em] text-[#63e6e2]">Packet Observatory</div><div className="font-display text-lg font-semibold tracking-tight">IPv6 CLI Lab</div></div></div><div className="flex items-center gap-3 text-xs text-[#98a8b0]"><span className="hidden sm:inline">TRAINING CONSOLE</span><span className="h-1.5 w-1.5 rounded-full bg-[#63e6e2] shadow-[0_0_10px_#63e6e2]" /><span className="font-mono">LOCAL SESSION</span></div></div></header>
    <LabSelector selectedLab={selectedLab} onSelect={(id) => { setSelectedLab(id); setHintVisible(false); }} />
    <div className="mx-auto grid max-w-[1500px] grid-cols-1 lg:grid-cols-[250px_1fr]"><aside className="border-b border-white/10 bg-[#0d151e] lg:min-h-[calc(100vh-73px)] lg:border-b-0 lg:border-r"><div className="p-5 lg:sticky lg:top-0"><div className="mb-7 flex items-center justify-between"><div><div className="instrument-label">LAB PATH</div><div className="mt-1 text-sm text-[#9eacb2]">IPv6 foundations</div></div><Gauge className="h-4 w-4 text-[#f5b74b]" /></div><nav className="space-y-1.5" aria-label="Lab steps">{steps.map((item, index) => { const done = completion[index]; const current = item.id === activeStep; return <button key={item.id} onClick={() => { if (item.device !== "BOTH" && item.device !== lab.activeDevice) switchDevice(item.device); }} className={`group flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left transition-all duration-200 ${current ? "bg-[#173038] text-white shadow-[inset_3px_0_0_#63e6e2]" : "text-[#82919a] hover:bg-white/[.04] hover:text-[#dce5e5]"}`}><span className={`font-mono text-[10px] ${current ? "text-[#63e6e2]" : done ? "text-[#f5b74b]" : "text-[#54626a]"}`}>{item.code}</span><span className="min-w-0 flex-1 truncate text-sm">{item.title}</span>{done ? <Check className="h-3.5 w-3.5 text-[#f5b74b]" /> : current ? <ChevronRight className="h-3.5 w-3.5 text-[#63e6e2]" /> : null}</button>; })}</nav><div className="mt-8 border-t border-white/10 pt-5"><div className="mb-2 flex justify-between font-mono text-[10px] uppercase tracking-wider text-[#77858d]"><span>Progress</span><span className="text-[#63e6e2]">{percent}%</span></div><div className="h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-[#63e6e2] transition-all duration-300" style={{ width: `${percent}%` }} /></div><p className="mt-3 text-xs leading-relaxed text-[#6d7b83]">Run the command. Read the evidence. Explain the path.</p></div></div></aside>
      <section className="relative min-w-0"><div className="absolute inset-0 opacity-35" style={{ backgroundImage: "url('/manus-storage/packet-observatory-texture_96a51270.jpg')", backgroundSize: "cover", backgroundPosition: "top right" }} /><div className="relative mx-auto max-w-[1240px] px-5 py-7 lg:px-10 lg:py-9"><div className="mb-6 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="instrument-label text-[#f5b74b]">{selectedCurriculum.domain} · {selectedLab === 1 ? statusLabel : "CURRICULUM BLUEPRINT"}</div><h1 className="mt-2 max-w-3xl font-display text-3xl font-semibold tracking-[-.03em] text-white md:text-5xl">{selectedLab === 1 ? <>Build the path.<br /><span className="text-[#63e6e2]">Trust the evidence.</span></> : <>{selectedCurriculum.title}<br /><span className="text-[#63e6e2]">Practice the signal.</span></>}</h1></div><div className="flex gap-2"><Button variant="outline" className="border-white/15 bg-[#101923]/70 text-[#aab8bd] hover:bg-white/10 hover:text-white" onClick={() => setShowGuide((v) => !v)}><CircleHelp className="mr-2 h-4 w-4" /> {showGuide ? "Hide brief" : "Show brief"}</Button><Button variant="outline" className="border-white/15 bg-[#101923]/70 text-[#aab8bd] hover:bg-white/10 hover:text-white" onClick={resetLab}><RotateCcw className="mr-2 h-4 w-4" /> Reset</Button></div></div>
        {selectedLab !== 1 && <section className="mb-7 grid gap-4 xl:grid-cols-[1.05fr_.95fr]"><div className="panel-surface p-5"><div className="instrument-label text-[#f5b74b]">CURRICULUM BLUEPRINT · {selectedCurriculum.code}</div><p className="mt-3 max-w-2xl text-base leading-7 text-[#c2cccf]">{selectedCurriculum.blurb}</p><div className="mt-5 flex flex-wrap gap-2">{selectedCurriculum.skills.map((skill) => <span key={skill} className="data-chip"><Check className="h-3.5 w-3.5 text-[#63e6e2]" /> {skill}</span>)}</div><div className="mt-5 border-t border-white/10 pt-4 font-mono text-[10px] uppercase tracking-wider text-[#77858d]">Topology · <span className="text-[#b6c3c6]">{selectedCurriculum.topology}</span></div></div><div className="panel-surface p-5"><div className="instrument-label text-[#63e6e2]">OBJECTIVES TO UNLOCK</div><div className="mt-3 space-y-3">{selectedCurriculum.steps.map((lesson, index) => <div key={lesson.title} className="flex gap-3"><span className="font-mono text-[10px] text-[#f5b74b]">0{index + 1}</span><div><div className="text-sm text-[#e0e6e6]">{lesson.title}</div><div className="mt-1 font-mono text-[11px] text-[#6f8189]">{lesson.command}</div></div></div>)}</div><div className="mt-5 rounded-lg border border-[#f5b74b]/20 bg-[#f5b74b]/10 px-3 py-2 text-xs leading-5 text-[#f3d590]">Select Lab 2 to enter the full IOS simulator; every command is validated against the active mode.</div></div></section>}
        {showGuide && <div className="mb-7 grid gap-4 xl:grid-cols-[1.15fr_.85fr]"><div className="relative overflow-hidden rounded-xl border border-white/10 bg-[#111c27]/90 p-5 shadow-2xl"><div className="absolute inset-y-0 right-0 w-1/2 opacity-30" style={{ backgroundImage: "url('/manus-storage/ipv6-route-atlas_06f29285.jpg')", backgroundSize: "cover", backgroundPosition: "center" }} /><div className="relative max-w-xl"><div className="instrument-label">MISSION BRIEF</div><p className="mt-3 max-w-lg text-base leading-7 text-[#c2cccf]">Configure a two-router IPv6-only path using the Cisco CLI. Loopbacks stand in for LANs so every route decision stays visible.</p><div className="mt-5 flex flex-wrap gap-2"><span className="data-chip"><Network className="h-3.5 w-3.5 text-[#63e6e2]" /> 2 routers</span><span className="data-chip"><Wifi className="h-3.5 w-3.5 text-[#63e6e2]" /> 1 transit /64</span><span className="data-chip"><TerminalSquare className="h-3.5 w-3.5 text-[#63e6e2]" /> 7 checks</span></div></div></div><div className="rounded-xl border border-[#63e6e2]/20 bg-[#0d171e]/80 p-5"><div className="instrument-label text-[#63e6e2]">ADDRESSING PLAN</div><div className="mt-4 space-y-3 font-mono text-xs"><div className="flex items-center justify-between border-b border-white/10 pb-3"><span className="text-[#74838b]">R1 transit</span><span className="text-[#dce5e5]">2001:db8:12:12::1/64</span></div><div className="flex items-center justify-between border-b border-white/10 pb-3"><span className="text-[#74838b]">R2 transit</span><span className="text-[#dce5e5]">2001:db8:12:12::2/64</span></div><div className="flex items-center justify-between border-b border-white/10 pb-3"><span className="text-[#74838b]">R1 loopback</span><span className="text-[#dce5e5]">2001:db8:1::1/64</span></div><div className="flex items-center justify-between"><span className="text-[#74838b]">R2 loopback</span><span className="text-[#dce5e5]">2001:db8:2::1/64</span></div></div></div></div>}
        <div className="grid gap-6 xl:grid-cols-[.86fr_1.14fr]"><div className="space-y-6"><section className="panel-surface overflow-hidden"><div className="flex items-center justify-between border-b border-white/10 px-5 py-4"><div><div className="instrument-label">TOPOLOGY / LIVE TRACE</div><div className="mt-1 text-sm text-[#aab8bd]">Current route under construction</div></div><span className="status-pill"><span className="status-dot" /> {completedCount ? "SIGNAL ACTIVE" : "STANDBY"}</span></div><div className="relative min-h-[246px] overflow-hidden px-6 py-9"><div className="absolute left-[20%] right-[20%] top-[48%] h-px bg-[#34505a]" /><div className={`packet-line ${completedCount > 0 ? "packet-line-active" : ""}`} /><div className="topology-node left-[12%] top-[32%]"><span className="node-label">R1</span><span className="node-sub">2001:db8:1::/64</span></div><div className="topology-node right-[12%] top-[32%]"><span className="node-label">R2</span><span className="node-sub">2001:db8:2::/64</span></div><div className="absolute left-1/2 top-[51%] -translate-x-1/2 font-mono text-[10px] tracking-widest text-[#63e6e2]">2001:DB8:12:12::/64</div><div className="absolute bottom-5 left-6 right-6 flex justify-between font-mono text-[10px] uppercase tracking-wider text-[#64747d]"><span>g0/0 · FE80::1</span><span>g0/0 · FE80::2</span></div></div></section><section className="panel-surface"><div className="flex items-center justify-between border-b border-white/10 px-5 py-4"><div><div className="instrument-label">CURRENT OBJECTIVE</div><div className="mt-1 font-display text-lg font-semibold text-white">{step.title}</div></div><span className="rounded-md bg-[#f5b74b]/10 px-2 py-1 font-mono text-[10px] text-[#f5b74b]">{step.device === "BOTH" ? "R1 + R2" : step.device}</span></div><div className="p-5"><p className="text-sm leading-6 text-[#b7c2c5]">{step.description}</p><div className="mt-5 flex gap-2"><Button className="bg-[#63e6e2] text-[#071014] hover:bg-[#83efec]" onClick={() => setHintVisible((v) => !v)}><CircleHelp className="mr-2 h-4 w-4" /> {hintVisible ? "Hide hint" : "Need a nudge?"}</Button>{hintVisible && <div className="flex-1 rounded-lg border border-[#f5b74b]/20 bg-[#f5b74b]/10 px-3 py-2 text-xs leading-5 text-[#f5d58b]">{step.hint}</div>}</div></div></section></div>
          <section className="terminal-shell"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/10 bg-[#111b24] px-5 py-3"><div className="flex items-center gap-2"><div className="flex gap-1.5"><span className="h-2.5 w-2.5 rounded-full bg-[#f07178]" /><span className="h-2.5 w-2.5 rounded-full bg-[#f5b74b]" /><span className="h-2.5 w-2.5 rounded-full bg-[#63e6e2]" /></div><span className="ml-2 font-mono text-[10px] uppercase tracking-[.18em] text-[#74848d]">ios-sim / console</span></div><div className="flex items-center gap-1 rounded-lg border border-white/10 bg-[#0b1118] p-1"><button onClick={() => switchDevice("R1")} className={`rounded px-3 py-1 font-mono text-[11px] transition ${lab.activeDevice === "R1" ? "bg-[#173038] text-[#63e6e2]" : "text-[#70818a] hover:text-white"}`}>R1</button><button onClick={() => switchDevice("R2")} className={`rounded px-3 py-1 font-mono text-[11px] transition ${lab.activeDevice === "R2" ? "bg-[#173038] text-[#63e6e2]" : "text-[#70818a] hover:text-white"}`}>R2</button></div></div><div className="terminal-output" aria-live="polite">{device.history.map((line, index) => <div key={`${line}-${index}`} className={`${line.startsWith("%") ? "text-[#f07178]" : line.startsWith("✓") ? "text-[#f5b74b]" : line.startsWith("Cisco") || line.startsWith("Press") ? "text-[#72848d]" : line.startsWith("R") ? "text-[#c8d4d7]" : "text-[#85959d]"}`}>{line || "\u00a0"}</div>)}<div className="mt-3 flex items-center gap-2"><span className="text-[#63e6e2]">{prompt}</span><input autoFocus value={command} onChange={(e) => setCommand(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submitCommand()} className="min-w-0 flex-1 bg-transparent font-mono text-sm text-white outline-none placeholder:text-[#42535c]" placeholder="type a command..." aria-label="Cisco CLI command" /></div></div><div className="flex flex-wrap items-center justify-between gap-3 border-t border-white/10 bg-[#0e1720] px-5 py-3"><div className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-wider text-[#667780]"><span className="h-1.5 w-1.5 rounded-full bg-[#63e6e2]" /> {lab.activeDevice} · {device.mode}{device.context ? ` · ${device.context}` : ""}</div><div className="flex gap-2"><Button variant="outline" size="sm" className="border-white/15 bg-transparent text-[#94a4aa] hover:bg-white/10 hover:text-white" onClick={copyHint}><Copy className="mr-2 h-3.5 w-3.5" /> Copy hint</Button><Button size="sm" className="bg-[#f5b74b] text-[#1c160b] hover:bg-[#ffca69]" onClick={runSuggested}><Play className="mr-2 h-3.5 w-3.5" /> Run suggested</Button></div></div></section></div><div className="mt-6 flex flex-col justify-between gap-3 border-t border-white/10 pt-5 text-xs text-[#687780] sm:flex-row"><span>Isolated training environment · Documentation prefixes only</span><a href="https://www.cisco.com/c/en/us/td/docs/ios/ipv6/configuration/guide/ipv6-xe-16-book-cat8000/m_ip6-addrg-bsc-con.html" target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-[#8ba8aa] hover:text-[#63e6e2]">Cisco IPv6 reference <ExternalLink className="h-3 w-3" /></a></div></div></section></div>
  </main>;
}
